    transform 0.6s ease,
    opacity 0.6s ease,
    box-shadow 0.3s ease;
}

.card:hover {
  transform: scale(2);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);
}

@keyframes fade {
  0% { opacity: 0; transform: translate(-50%, -60%); }
  20% { opacity: 1; transform: translate(-50%, -50%); }
  80% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%, -40%); }
}

</style>