function generateDesc(type, card) {
  switch(type) {
    case "attack":
      return `造成 ${card.dmg} 點傷害`;
    case "ranged_attack":
      return `造成 ${card.dmg} 點傷害`;
    case "magic_attack":
      return `造成 ${card.dmg} 點魔法傷害`;
    case "heal":
      return `回復 ${card.heal} 點生命`;
    case "defend":
      return `增加 ${card.def} 點防禦`;
    case "magic_defend":
      return `增加 ${card.def} 點魔法防禦`;
    case "buff_attack":
      return `攻擊力提升 ${card.buffDmg} 點`;
    default:
      return "";
  }
}
