<template>
  <div 
    class="fixed inset-0 bg-black/60 flex justify-center items-center z-50 transition duration-300"
    :class="showshop ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'"
  >

    <!-- 主視窗容器 -->
    <div class="bg-gray-900/90 w-[80%] max-w-5xl p-8 rounded-2xl shadow-2xl border border-yellow-600 flex flex-col items-center">

      <!-- 商店標題 -->
       <div class="flex justify-between items-center mb-8 w-full">
         <div class="text-4xl font-bold mb-8 text-yellow-300 drop-shadow-lg">
        🏪 商店
        </div>
        <div class="text-4xl font-bold mb-8 text-yellow-300 drop-shadow-lg">
        🪙 金幣:{{ player.coin }}
        </div>
       </div>

      <!-- 三大區塊 -->
      <div class="w-full space-y-12 overflow-y-auto max-h-[70vh] pr-2">

        <!-- 第一排：卡牌商店 -->
        <section class="bg-gray-800/60 p-6 rounded-xl shadow-lg border border-gray-700">
          <h2 class="text-2xl font-bold mb-5 text-blue-300">📘 卡牌區</h2>

          <div class="grid grid-cols-5 gap-6">
            <template v-if="cardsForSale.length > 0">
              <div
              v-for="(card,index) in cardsForSale"
              :key="card.id + '-' + index"
              class="bg-gray-900 rounded-xl shadow-md hover:scale-105 duration-150 cursor-pointer border border-gray-700"
              @click="buyCard(card)"
              >
                <img :src="card.img" class="w-full h-[280px] object-cover rounded-md" />
                <div class="text-center text-yellow-300 text-lg">🪙 {{ card.price }}</div>
              </div>
            </template>
            <template v-else>
                <div class="col-span-5 text-center text-gray-400 text-lg">
                  售完
                </div>
            </template>
          </div>
        </section>

        <!-- 第二排：裝備商店 -->
        <section class="bg-gray-800/60 p-6 rounded-xl shadow-lg border border-gray-700">
          <h2 class="text-2xl font-bold mb-5 text-green-300">🛡 裝備區</h2>

          <div class="grid grid-cols-5 gap-6">
            <div
              v-for="equip in equipsForSale"
              :key="equip.id"
              class="bg-gray-900 p-3 rounded-xl shadow-md hover:scale-105 duration-150 cursor-pointer border border-gray-700"
            >
              <img :src="equip.img" class="w-full h-[140px] object-cover rounded-md" />
              <div class="text-center text-yellow-300 text-lg">🪙 {{ equip.price }}</div>
            </div>
          </div>
        </section>

        <!-- 第三排：藥水商店 -->
        <section class="bg-gray-800/60 p-6 rounded-xl shadow-lg border border-gray-700">
          <h2 class="text-2xl font-bold mb-5 text-purple-300">🧪 藥水區</h2>

          <div class="grid grid-cols-5 gap-6">
            <template v-if="potionsForSale.length > 0">
              <div
                v-for="(potion, index) in potionsForSale"
                :key="potion.id + '-' + index"
                class="bg-gray-900 rounded-xl shadow-md hover:scale-105 duration-150 cursor-pointer border border-gray-700"
                @click="buyPotion(potion)"
              >
                <img :src="potion.img" class="w-full h-[280px] object-cover rounded-md" />
                <div class="text-center text-yellow-300 text-lg">🪙 {{ potion.price }}</div>
              </div>
            </template>
            <template v-else>
              <div class="col-span-5 text-center text-gray-400 text-lg">
                售完
              </div>
            </template>
          </div>
        </section>
      </div>

      <!-- 返回按鈕 -->
      <button
        @click="$emit('close-shop')"
        class="mt-8 px-10 py-3 bg-yellow-600 rounded-xl hover:bg-yellow-500 text-lg font-bold shadow-lg"
      >
        返回
      </button>

    </div>

  </div>
</template>

<script>
export default {
  name: "GameShop",
  props: {
    player: Object,
    potions: Object,
    cards: Object,
    warrior: Object,
    mage: Object,
    showshop: Boolean
  },
  data() {
    return {
      cardsForSale: [],
      potionsForSale: []
    }
  },
  methods: {
    generateShopItems() {
      //卡牌
      if(this.player.job === "warrior") { 
        this.cardsForSale = []; 
        for (let i = 0; i < 5; i++) { 
          const randomIndex = Math.floor(Math.random() * this.warrior.deck.length); 
          const key = this.warrior.deck[randomIndex]; 
          const card = this.cards[key]; 
          this.cardsForSale.push({ 
            id: card.id, 
            img: card.img, 
            price: card.price 
          }) 
        } 
      } 
      else if(this.player.job === "mage") { 
        this.cardsForSale = []; 
        for (let i = 0; i < 5; i++) { 
          const randomIndex = Math.floor(Math.random() * this.mage.deck.length); 
          const key = this.mage.deck[randomIndex]; 
          const card = this.cards[key]; 
          this.cardsForSale.push({ 
            id: card.id, 
            img: card.img, 
            price: card.price 
          }) 
        } 
      }

      // 藥水
      this.potionsForSale = []; 
      const potionKeys = Object.keys(this.potions); 
      for(let i = 0; i < 5; i++) { 
        const randomIndex = Math.floor(Math.random() * potionKeys.length); 
        const key = potionKeys[randomIndex]; 
        const potion = this.potions[key]; 
        this.potionsForSale.push({ 
          id: potion.id, 
          img: potion.img, 
          price: potion.price 
        }) 
      }
    },

    buyCard(card) {
      this.$emit("buy-card", card.id, card.price, this.cardsForSale);
    },

    buyPotion(potion) {
      this.$emit("buy-potion", potion.id, potion.price, this.potionsForSale);
    },
  },
  watch: {
    'player.job'(newJob) {
      if(newJob) {
        this.generateShopItems();
      }
    }
  }
}
</script>
