<template>
  <div v-if="showRewards" class="reward-box">
    <div 
      v-for="(r, index) in rewards" 
      :key="r.id" 
      class="reward"
      :class="{ selected: selectedIndex === index, disappear: selectedIndex !== null && selectedIndex !== index }"
      @click="onChoose(index, $event.currentTarget)"
    >
      {{ r.name }}
    </div>
  </div>
</template>

<script>
export default {
  props: {
    rewards: Array,
    showRewards: Boolean
  },
  data() {
    return {
      selectedIndex: null
    }
  },
  methods: {
    onChoose(index, cardEl) {
      if (this.selectedIndex !== null) return;

      this.selectedIndex = index;
      const reward = this.rewards[index];

      cardEl.classList.add("no-hover");

      this.$el.querySelectorAll(".reward").forEach((r, i) => {
        if (i !== index) r.classList.add("no-hover");
      });

      this.$emit('selected', reward);

      setTimeout(() => {
        this.$emit('close');
      }, 600);
    }
  }
}
</script>

<style scoped>
.reward-box {
  height: 300px;
  width: 800px;
  position: absolute;
  top: 30%;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 120px;
}

.reward {
  width: 160px;
  height: 220px;
  padding: 10px;
  background: linear-gradient(#ffe066, #ffbd2e);
  border: 3px solid #d4a017;
  box-shadow: 0 4px 10px rgba(0,0,0,0.3);
  transition: 
    transform 0.6s ease,
    opacity 0.6s ease,  
    box-shadow 0.3s ease;
  cursor: pointer;
}


.reward:hover {
  transform: translateY(-10px) scale(1.5);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.2);
}

.reward.no-hover:hover {
  transform: none;
  box-shadow: none;
}

.reward.selected {
  transform: translateY(-120px) scale(1.3);
  opacity: 0;
  z-index: 3;
}


.reward.disappear {
  transform: translateY(50px) scale(0.8);
  opacity: 0;
}
</style>
